(* [comment removed for export] *)
Fixpoint art_w4s (M : word -> option byte) (dst : Z) (ws : list Z) : word -> option byte :=
  match ws with [] => M | w :: ws' => art_w4s (Wn 4 M dst w) (dst + 4) ws' end.

Lemma art_w4s_grows : forall ws M dst, mem_grows M (art_w4s M dst ws).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S80!1+^E+4|30;%~R!1+2!1,1|600;!1+3!1+2!1,11%M;R2%dst;R+4!2'cS#2!3'cT#2#1#3}4!4'P4#2#1#5|20;!2'@#1!1,86$ws;R0!5'cR+4$ws;R03$M;R2$dst;R+4vd!1'cU#2!2'cS#2!3'cT#2#1!1,^?+4$w;R+4$ws;R0$IH;R3$M;R2$dst;R+4vd!5'cV#25!3'cT57#4!4'cW4#2#1#5!2#357!2'cS#2!3'cT#2#1!3,^<+4#5#4#1").
Qed.
